"""gRPC implementation of the source client (synchronous + background threads).

Threading model:

* A supervisor thread owns the connect/reconnect loop. Each iteration registers
  one source with ``SourceDeclared`` and waits for ``RegistrationAccepted``.
* The control plane runs on the supervisor thread: it sends queued
  ``ClientEvent`` messages and handles ``Open`` / ``Close`` / ``Shutdown``.
* A sender thread runs ``StreamSamples`` only after the Source Bus opens this
  registered source. It maps each frame to ``SampleBatch{source_id, ...}``.

``submit()`` only touches the bounded frame queue, so the customer's control loop
never blocks on the network.
"""

from __future__ import annotations

import queue
import threading
from collections.abc import Iterator
from dataclasses import dataclass

import grpc

from loop_sdk.gen.v1 import source_ingest_pb2 as pb2
from loop_sdk.gen.v1 import source_ingest_pb2_grpc as pb2_grpc
from loop_sdk.source.domain.camera import CameraOpenResult, CameraSetting, OnCameraOpen
from loop_sdk.source.domain.config import OnSelectRobotConfig, RobotConfig
from loop_sdk.source.domain.frame import FrameSample
from loop_sdk.source.domain.schema import SourceSchema
from loop_sdk.source.domain.source_exception import NotConnectedError
from loop_sdk.source.domain.source_kind import SourceKind
from loop_sdk.source.domain.stats import SendStats
from loop_sdk.source.outbound import proto_mapping
from loop_sdk.source.outbound.frame_queue import FrameQueue
from loop_sdk.source.outbound.grpc_channel_options import GRPC_CHANNEL_OPTIONS
from loop_sdk.source.port.source_client import SourceClient


class _Stats:
    """Mutable, lock-guarded counters projected into the immutable ``SendStats``."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self.enqueued = 0
        self.sent = 0
        self.failed = 0
        self.reconnects = 0
        self.connected = False

    def snapshot(self, dropped: int) -> SendStats:
        with self._lock:
            return SendStats(
                enqueued=self.enqueued,
                sent=self.sent,
                failed=self.failed,
                dropped=dropped,
                reconnects=self.reconnects,
                connected=self.connected,
            )

    def incr(self, field: str, by: int = 1) -> None:
        with self._lock:
            setattr(self, field, getattr(self, field) + by)

    def set_connected(self, value: bool) -> None:
        with self._lock:
            self.connected = value


@dataclass
class _DataPlaneSession:
    session_id: str
    source_id: str
    ended: threading.Event


class GrpcSourceClient(SourceClient):
    """Drive one Source Bus connection over synchronous gRPC with background threads."""

    def __init__(
        self,
        loop_addr: str,
        client_id: str,
        version: str,
        reconnect_backoff_seconds: float,
        reconnect_backoff_max_seconds: float,
        on_select: OnSelectRobotConfig | None,
        on_camera_open: OnCameraOpen | None = None,
    ) -> None:
        self._loop_addr = loop_addr
        self._client_id = client_id
        self._version = version
        self._reconnect_backoff_seconds = reconnect_backoff_seconds
        self._reconnect_backoff_max_seconds = reconnect_backoff_max_seconds
        self._on_select = on_select
        self._on_camera_open = on_camera_open

        self._schema: SourceSchema | None = None
        self._source_id: str | None = None
        self._frames = FrameQueue()
        self._stats = _Stats()
        self._closed = threading.Event()
        self._supervisor: threading.Thread | None = None
        # The in-flight Connect call, cancelled on shutdown/close to unblock the
        # response iterator (closing only the request side does not end it).
        self._active_call: grpc.Call | None = None

        # Per-session state, reset on each (re)connect.
        self._events: queue.SimpleQueue[pb2.ClientEvent | None] = queue.SimpleQueue()
        self._data_plane_sessions: queue.SimpleQueue[_DataPlaneSession | None] = queue.SimpleQueue()
        self._session_lock = threading.Lock()
        self._active_data_plane_session: _DataPlaneSession | None = None
        self._opened = False
        self._session_id = ""
        self._session_ready = threading.Event()
        self._session_ended = threading.Event()

    # -- SourceClient contract -------------------------------------------------

    @property
    def source_id(self) -> str | None:
        return self._source_id

    def start(self, schema: SourceSchema) -> None:
        self._schema = schema
        self._supervisor = threading.Thread(target=self._supervise, name="source-supervisor", daemon=True)
        self._supervisor.start()

    def submit(self, frame: FrameSample) -> None:
        if self._schema is None:
            raise NotConnectedError("start() must be called before submit()")
        self._stats.incr("enqueued")
        if not self._session_lock.acquire(blocking=False):
            return
        try:
            active = self._active_data_plane_session
            if active is None or not self._opened or active.ended.is_set():
                return
            self._frames.put(frame)
        finally:
            self._session_lock.release()

    def report_error(self, code: str, message: str = "") -> None:
        if self._schema is None:
            raise NotConnectedError("start() must be called before report_error()")
        if self._source_id is None:
            raise NotConnectedError("registration must complete before report_error()")
        self._events.put(_error_event(self._client_id, self._source_id, code, message))

    def stats(self) -> SendStats:
        return self._stats.snapshot(self._frames.dropped)

    def close(self) -> None:
        self._closed.set()
        self._frames.close()
        self._events.put(None)
        self._cancel_active_call()
        supervisor = self._supervisor
        if supervisor is not None:
            supervisor.join(timeout=5.0)

    # -- supervisor / reconnect loop ------------------------------------------

    def _supervise(self) -> None:
        backoff = self._reconnect_backoff_seconds
        first_attempt = True
        while not self._closed.is_set():
            if not first_attempt:
                self._stats.incr("reconnects")
            first_attempt = False
            reached_live = self._run_session()
            if self._closed.is_set():
                return
            if reached_live:
                backoff = self._reconnect_backoff_seconds
            self._sleep_backoff(backoff)
            backoff = min(backoff * 2, self._reconnect_backoff_max_seconds)

    def _run_session(self) -> bool:
        """Run one connection. Return whether registration was accepted."""
        self._reset_session()
        sender: threading.Thread | None = None
        reached_live = False
        try:
            channel = grpc.insecure_channel(self._loop_addr, options=GRPC_CHANNEL_OPTIONS)
            with channel:
                assert self._schema is not None
                stub = pb2_grpc.SourceIngestServiceStub(channel)
                self._events.put(_source_declared_event(self._client_id, self._schema, self._version))
                sender = threading.Thread(target=self._run_sender, args=(stub,), name="source-sender", daemon=True)
                sender.start()
                call = stub.Connect(self._drain_events())
                self._active_call = call
                self._stats.set_connected(True)
                for command in call:
                    if command.WhichOneof("command") == "registration_accepted":
                        reached_live = True
                    self._handle_command(command)
        except grpc.RpcError:
            pass
        finally:
            self._active_call = None
            self._stats.set_connected(False)
            self._end_session(sender)
        return reached_live

    def _reset_session(self) -> None:
        self._events = queue.SimpleQueue()
        self._data_plane_sessions = queue.SimpleQueue()
        with self._session_lock:
            self._source_id = None
            self._opened = False
            self._session_id = ""
            self._active_data_plane_session = None
            self._session_ready.clear()
            self._session_ended.clear()
        self._frames.clear()
        self._frames.reset_wake()

    def _end_session(self, sender: threading.Thread | None) -> None:
        # Unblock the sender's StreamSamples iterator so the thread can exit
        # without closing the shared frame queue (which survives reconnects).
        with self._session_lock:
            active = self._active_data_plane_session
            self._opened = False
            self._active_data_plane_session = None
            self._session_ended.set()
            self._session_ready.set()
        if active is not None:
            active.ended.set()
        self._data_plane_sessions.put(None)
        self._events.put(None)
        self._frames.wake()
        if sender is not None:
            sender.join(timeout=2.0)

    def _sleep_backoff(self, seconds: float) -> None:
        # Wait, but wake immediately if close() is called.
        self._closed.wait(timeout=seconds)

    def _cancel_active_call(self) -> None:
        # Cancel the in-flight Connect so the response iterator unblocks. Safe to
        # call when there is no active call or it has already finished.
        call = self._active_call
        if call is None:
            return
        call.cancel()

    # -- control plane ---------------------------------------------------------

    def _drain_events(self) -> Iterator[pb2.ClientEvent]:
        while True:
            event = self._events.get()
            if event is None:
                return
            yield event

    def _handle_command(self, command: pb2.RecorderCommand) -> None:
        which = command.WhichOneof("command")
        if which == "registration_accepted":
            self._source_id = command.registration_accepted.source_id
            return
        if which == "open":
            self._handle_open(command.open)
            return
        if which == "close":
            self._handle_close(command.close)
            return
        if which == "shutdown":
            self._events.put(None)
            self._cancel_active_call()
            return

    def _handle_open(self, open_command: pb2.OpenCommand) -> None:
        data_plane_open = self._open_includes_data_plane(open_command)
        if data_plane_open and self._data_plane_is_open():
            return
        if not self._apply_robot_config(open_command):
            return
        self._apply_camera_open(open_command)
        if not data_plane_open:
            return
        if not self._begin_data_plane_session(open_command.session_id):
            return
        self._report_default_data_plane_started(open_command)

    def _data_plane_is_open(self) -> bool:
        with self._session_lock:
            return self._opened

    def _begin_data_plane_session(self, session_id: str) -> bool:
        source_id = self._source_id
        if source_id is None:
            return False
        session = _DataPlaneSession(session_id=session_id, source_id=source_id, ended=threading.Event())
        with self._session_lock:
            if self._opened:
                return False
            self._frames.clear()
            self._opened = True
            self._session_id = session_id
            self._session_ended = session.ended
            self._active_data_plane_session = session
            self._session_ready.set()
            self._data_plane_sessions.put(session)
        return True

    def _open_includes_data_plane(self, open_command: pb2.OpenCommand) -> bool:
        if open_command.WhichOneof("params") == "camera":
            return False
        if self._schema is None:
            return True
        return self._schema.kind is not SourceKind.CAMERA

    def _report_default_data_plane_started(self, open_command: pb2.OpenCommand) -> None:
        if self._open_has_negotiated_state(open_command):
            return
        source_id = self._source_id
        if source_id is None:
            return
        self._events.put(_started_event(self._client_id, open_command.session_id, source_id))

    def _open_has_negotiated_state(self, open_command: pb2.OpenCommand) -> bool:
        which = open_command.WhichOneof("params")
        return which == "robot" and open_command.robot.HasField("requested_config")

    def _apply_robot_config(self, open_command: pb2.OpenCommand) -> bool:
        if open_command.WhichOneof("params") != "robot":
            return True
        if not open_command.robot.HasField("requested_config"):
            return True
        requested = proto_mapping.robot_config_from_pb(open_command.robot.requested_config)
        return self._negotiate_robot_config(open_command.session_id, requested)

    def _negotiate_robot_config(self, session_id: str, requested: RobotConfig) -> bool:
        source_id = self._source_id
        if source_id is None:
            return False
        if self._on_select is None:
            self._events.put(_failed_event(self._client_id, session_id, source_id, "no on_select callback"))
            return False
        try:
            applied = self._on_select(requested)
        except Exception as error:  # user callback: any failure means the source cannot open
            self._events.put(_failed_event(self._client_id, session_id, source_id, str(error)))
            return False
        self._events.put(_applied_event(self._client_id, session_id, source_id, applied or requested))
        return True

    def _apply_camera_open(self, open_command: pb2.OpenCommand) -> None:
        if open_command.WhichOneof("params") != "camera":
            return
        source_id = self._source_id
        if source_id is None:
            return
        requested: CameraSetting | None = None
        try:
            requested = (
                proto_mapping.camera_setting_from_pb(open_command.camera.requested_setting)
                if open_command.camera.HasField("requested_setting")
                else None
            )
        except ValueError as error:
            self._events.put(_failed_event(self._client_id, open_command.session_id, source_id, str(error)))
            return
        self._negotiate_camera_source(open_command.session_id, source_id, requested)

    def _negotiate_camera_source(
        self,
        session_id: str,
        source_id: str,
        requested: CameraSetting | None,
    ) -> None:
        if self._on_camera_open is None:
            if requested is not None:
                self._events.put(
                    _failed_event(
                        self._client_id,
                        session_id,
                        source_id,
                        "no on_camera_open callback to apply camera setting",
                    )
                )
                return
            self._events.put(_camera_applied_event(self._client_id, session_id, source_id, CameraOpenResult()))
            return
        try:
            result = self._on_camera_open(requested)
        except Exception as error:  # user callback: any failure means the source cannot open
            self._events.put(_failed_event(self._client_id, session_id, source_id, str(error)))
            return
        self._events.put(
            _camera_applied_event(
                self._client_id,
                session_id,
                source_id,
                result or CameraOpenResult(applied_setting=requested),
            )
        )

    def _handle_close(self, close_command: pb2.Close) -> None:
        # Stop the sender but keep the Connect control stream up so the server can
        # re-open or shut down cleanly. The frame queue survives.
        with self._session_lock:
            if close_command.session_id and close_command.session_id != self._session_id:
                return
            active = self._active_data_plane_session
            self._opened = False
            self._active_data_plane_session = None
            self._session_ended.set()
            self._session_ready.set()
        if active is not None:
            active.ended.set()
            self._frames.wake()

    # -- data plane ------------------------------------------------------------

    def _run_sender(self, stub: pb2_grpc.SourceIngestServiceStub) -> None:
        while not self._closed.is_set():
            session = self._data_plane_sessions.get()
            if session is None or self._closed.is_set():
                return
            if session.ended.is_set():
                self._frames.reset_wake()
                self._finish_data_plane_session(session)
                continue
            try:
                stub.StreamSamples(self._drain_batches(session))
            except grpc.RpcError:
                self._stats.incr("failed")
            finally:
                self._frames.reset_wake()
                self._finish_data_plane_session(session)

    def _finish_data_plane_session(self, session: _DataPlaneSession) -> None:
        session.ended.set()
        clear_pending = False
        with self._session_lock:
            if self._active_data_plane_session is session:
                self._opened = False
                self._active_data_plane_session = None
                self._session_ended.set()
                clear_pending = True
        if clear_pending:
            self._frames.clear()

    def _drain_batches(self, session: _DataPlaneSession) -> Iterator[pb2.SampleBatch]:
        while not session.ended.is_set():
            frame = self._frames.get()
            if frame is None:
                return
            if session.ended.is_set():
                return
            yield proto_mapping.sample_batch(frame, session.session_id, session.source_id)
            self._stats.incr("sent")


def _source_declared_event(client_id: str, schema: SourceSchema, version: str) -> pb2.ClientEvent:
    event = pb2.ClientEvent(client_id=client_id)
    event.source_declared.CopyFrom(proto_mapping.source_declared(schema, version))
    return event


def _error_event(client_id: str, source_id: str, code: str, message: str) -> pb2.ClientEvent:
    event = pb2.ClientEvent(client_id=client_id)
    event.error.CopyFrom(pb2.ClientError(code=code, message=message, source_id=source_id))
    return event


def _started_event(client_id: str, session_id: str, source_id: str) -> pb2.ClientEvent:
    event = pb2.ClientEvent(client_id=client_id)
    event.stream_state_changed.CopyFrom(
        pb2.StreamStateChanged(session_id=session_id, source_id=source_id, state=pb2.STREAM_STATE_STARTED)
    )
    return event


def _applied_event(client_id: str, session_id: str, source_id: str, applied: RobotConfig) -> pb2.ClientEvent:
    event = pb2.ClientEvent(client_id=client_id)
    changed = pb2.StreamStateChanged(session_id=session_id, source_id=source_id, state=pb2.STREAM_STATE_STARTED)
    changed.robot.CopyFrom(proto_mapping.robot_config_to_pb(applied))
    event.stream_state_changed.CopyFrom(changed)
    return event


def _camera_applied_event(
    client_id: str,
    session_id: str,
    source_id: str,
    applied: CameraOpenResult,
) -> pb2.ClientEvent:
    event = pb2.ClientEvent(client_id=client_id)
    changed = pb2.StreamStateChanged(session_id=session_id, source_id=source_id, state=pb2.STREAM_STATE_STARTED)
    changed.camera.CopyFrom(proto_mapping.camera_open_result_to_pb(applied))
    event.stream_state_changed.CopyFrom(changed)
    return event


def _failed_event(client_id: str, session_id: str, source_id: str, detail: str) -> pb2.ClientEvent:
    event = pb2.ClientEvent(client_id=client_id)
    event.stream_state_changed.CopyFrom(
        pb2.StreamStateChanged(
            session_id=session_id,
            source_id=source_id,
            state=pb2.STREAM_STATE_FAILED,
            detail=detail,
        )
    )
    return event
